<?php $title='Offers';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO offers(title,description,image,active) VALUES(?,?,?,1)")->execute([trim($_POST['title']),trim($_POST['description']),trim($_POST['image'])]);}$offers=$pdo->query("SELECT * FROM offers ORDER BY id DESC")->fetchAll();?><h1>Offers</h1><form method="post" class="card border-0 shadow-sm p-3 mb-4"><div class="row g-2"><div class="col-md-4"><input required name="title" class="form-control" placeholder="Offer title"></div><div class="col-md-4"><input name="image" class="form-control" placeholder="Image URL"></div><div class="col-md-4"><input name="description" class="form-control" placeholder="Description"></div><div class="col-12"><button class="btn btn-primary">Add Offer</button></div></div></form><div class="row g-3"><?php foreach($offers as $o):?><div class="col-md-6"><div class="card border-0 shadow-sm p-3"><h5><?=e($o['title'])?></h5><p><?=e($o['description'])?></p></div></div><?php endforeach;?></div><?php require 'includes/footer.php';?>